window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-19abcb0e490c8c0f"]={"versions": [{"id": "FIG-19abcb0e490c8c0f", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Architektur- und Schichtenmodell der AUTOSAR Classic Platform (AUTOSAR Basic Software Architecture). Das Blockschaltbild visualisiert die Einbettung des PDU Routers (PDU Router / Pdur) in die AUTOSAR-Kommunikationsarchitektur über zwei primäre Schichten: „Communication Services“ (Teil der Service-Schicht) und „Communication Hardware Abstraction“ (Kommunikations-Hardwareabstraktionsschicht). Der PDU Router fungiert dabei als zentrales Vermittlungsglied für I-PDUs zwischen oberen Kommunikationsdiensten, Transportprotokollen und busspezifischen Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert die beteiligten BSW-Module in Schichten und Funktionsgruppen:</p>\n<ul class=\"fig-list\">\n<li><strong>Communication Services (obere Schicht, violett hinterlegt):</strong></li>\n<li><strong>PDU Router</strong> (gelb hervorgehoben): Zentrale Vermittlungseinheit mit L-förmiger Topologie, die I-PDUs zwischen oberen Schichten, dem Multiplexer, Transportprotokollen und Hardware-Schnittstellen routet.</li>\n<li>Obere PDU-Nutzer/Quellen (orange):</li>\n<li><code>AUTOSAR COM</code>: Signalbasierte Kommunikation.</li>\n<li><code>Diagnostic Com.</code> (<code>Dcm</code> / Diagnostic Communication): Diagnosekommunikation.</li>\n<li><code>Debugging</code>: BSW-Debugging-Dienst.</li>\n<li><code>IPDU Multiplexer</code> (<code>IpduM</code>): Multiplexen und Demultiplexen von I-PDUs, links an den PDU Router angrenzend.</li>\n<li><code>Generic NM Interface</code>: Generische Netzwerkmanagement-Schnittstelle.</li>\n<li>Protokoll- und Zustandsmodule (blau):</li>\n<li><code>&lt;module&gt; Transport Protocol</code>: Busspezifisches Transportprotokoll (z. B. CanTp, FrTp, LinTp, FlexRayArTp), unterhalb des horizontalen Schenkels des PDU Routers angeordnet.</li>\n<li><code>&lt;module&gt; State Manager</code>: Busspezifischer Zustandsmanager (z. B. CanSM, FrSM, LinSM).</li>\n<li><code>&lt;module&gt; NM</code>: Busspezifisches Netzwerkmanagement (z. B. CanNm, FrNm).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Communication Hardware Abstraction (untere Schicht, grün hinterlegt):</strong></li>\n<li><code>&lt;module&gt; Interface</code> (blau): Busspezifische Schnittstelle (z. B. CanIf, FrIf, LinIf, EthIf), die direkt mit dem PDU Router, dem Transportprotokoll und dem State Manager interagiert.</li>\n<li>Zwei untergeordnete, unbeschriftete Modulblöcke (blau) unterhalb der busspezifischen Schnittstelle (repräsentieren Transceiver- und Treiberabstraktion).</li>\n</ul>\n<p class=\"fig-p\">Schnittstellen und Abhängigkeiten werden über die relative räumliche Lage und Kontiguität der Modulblöcke ausgedrückt (vertikales und horizontales I-PDU-Routing).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Modul- und Schichtendiagramm enthält die Abbildung keine Zeitachsen, Sequenznummern oder Nachrichtenpfeile. Der Kontroll- und Datenfluss ergibt sich aus der strukturellen Anordnung:</p>\n<ul class=\"fig-list\">\n<li>Datenübertragung und Routing von I-PDUs erfolgen zwischen <code>AUTOSAR COM</code>, <code>Diagnostic Com.</code> bzw. <code>Debugging</code> und dem <code>PDU Router</code>.</li>\n<li>Der <code>PDU Router</code> leitet I-PDUs entweder direkt an <code>&lt;module&gt; Interface</code> oder an <code>&lt;module&gt; Transport Protocol</code> zur Segmentierung/Reassemblierung weiter.</li>\n<li><code>IPDU Multiplexer</code> tauscht Daten mit dem PDU Router aus, um Multiplex-PDUs vor der Weiterleitung zusammenzusetzen oder aufzuteilen.</li>\n<li>Zustands- und Netzwerkmanagement (<code>&lt;module&gt; State Manager</code>, <code>&lt;module&gt; NM</code>, <code>Generic NM Interface</code>) interagieren vertikal mit <code>&lt;module&gt; Interface</code>, ohne den PDU Router zu passieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert die fundamentale Schichtenarchitektur und BSW-Modulbeziehungen für die Implementierung und Konfiguration des PDU Routers (<code>AUTOSAR_SWS_PDURouter</code>):</p>\n<ul class=\"fig-list\">\n<li>Modulgrenzen: Der PDU Router darf Schnittstellen nur zu den dargestellten Nachbarmodulen (COM, Dcm, Debugging, IpduM, Transport Protocols, Communication Interfaces) aufweisen.</li>\n<li>Keine direkte Anbindung des PDU Routers an Transceiver oder Treiber; diese verbleiben strikt unterhalb von <code>&lt;module&gt; Interface</code>.</li>\n<li>Netzwerkmanagement- und State-Management-Module laufen am PDU Router vorbei direkt auf die Schicht der Kommunikations-Hardwareabstraktion.</li>\n<li>Platzhalter <code>&lt;module&gt;</code> steht stellvertretend für busspezifische Ausprägungen (CAN, LIN, FlexRay, Ethernet).</li>\n</ul>"}, {"id": "FIG-d9d6dc4d731ac15d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Architektur- und Schichtenmodell der AUTOSAR Classic Platform (AUTOSAR Basic Software Architecture). Das Blockschaltbild visualisiert die Einbettung des PDU Routers (PDU Router / Pdur) in die AUTOSAR-Kommunikationsarchitektur über zwei primäre Schichten: „Communication Services“ (Teil der Service-Schicht) und „Communication Hardware Abstraction“ (Kommunikations-Hardwareabstraktionsschicht). Der PDU Router fungiert dabei als zentrales Vermittlungsglied für I-PDUs zwischen oberen Kommunikationsdiensten, Transportprotokollen und busspezifischen Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert die beteiligten BSW-Module in Schichten und Funktionsgruppen:</p>\n<ul class=\"fig-list\">\n<li><strong>Communication Services (obere Schicht, violett hinterlegt):</strong></li>\n<li><strong>PDU Router</strong> (gelb hervorgehoben): Zentrale Vermittlungseinheit mit L-förmiger Topologie zur I-PDU-Verteilung.</li>\n<li>Obere PDU-Nutzer/Quellen (orange):</li>\n<li><code>AUTOSAR COM</code>: Signalbasierte Kommunikation.</li>\n<li><code>Diagnostic Com. Manager</code> (<code>Dcm</code>): Diagnose-Kommunikationsmanager.</li>\n<li><code>Debugging</code>: BSW-Debugging-Dienst.</li>\n<li><code>IPDU Multiplexer</code> (<code>IpduM</code>): Multiplexen und Demultiplexen von I-PDUs.</li>\n<li><code>Generic NM Interface</code>: Generische Netzwerkmanagement-Schnittstelle.</li>\n<li>Protokoll- und Zustandsmodule (blau):</li>\n<li><code>&lt;module&gt; Transport Protocol</code>: Busspezifisches Transportprotokoll (z. B. CanTp, FrTp, LinTp).</li>\n<li><code>&lt;module&gt; State Manager</code>: Busspezifischer Zustandsmanager (z. B. CanSM, FrSM, LinSM).</li>\n<li><code>&lt;module&gt; NM</code>: Busspezifisches Netzwerkmanagement (z. B. CanNm, FrNm).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Communication Hardware Abstraction (untere Schicht, grün hinterlegt):</strong></li>\n<li><code>&lt;module&gt; Interface</code> (blau): Busspezifische Schnittstelle zur Kommunikation mit PDU Router, Transportprotokoll und Zustandsmanagement.</li>\n<li><code>&lt;module&gt; Transceiver</code>: Transceiver-Treiber / Abstraktion unterhalb von <code>&lt;module&gt; Interface</code>.</li>\n<li><code>&lt;module&gt; Driver</code>: Hardware-Treiber / Abstraktion unterhalb von <code>&lt;module&gt; Interface</code>.</li>\n</ul>\n<p class=\"fig-p\">Die Interaktionsbeziehungen basieren auf der direkten Nachbarschaft der Schichten und Modulkanten.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Modul- und Schichtendiagramm enthält die Abbildung keine Zeitachsen, Sequenznummern oder Nachrichtenpfeile. Der Kontroll- und Datenfluss ergibt sich aus der strukturellen Anordnung:</p>\n<ul class=\"fig-list\">\n<li>Datenübertragung und Routing von I-PDUs erfolgen zwischen <code>AUTOSAR COM</code>, <code>Diagnostic Com.</code> bzw. <code>Debugging</code> und dem <code>PDU Router</code>.</li>\n<li>Der <code>PDU Router</code> leitet I-PDUs entweder direkt an <code>&lt;module&gt; Interface</code> oder an <code>&lt;module&gt; Transport Protocol</code> zur Segmentierung/Reassemblierung weiter.</li>\n<li><code>IPDU Multiplexer</code> tauscht Daten mit dem PDU Router aus, um Multiplex-PDUs vor der Weiterleitung zusammenzusetzen oder aufzuteilen.</li>\n<li>Zustands- und Netzwerkmanagement (<code>&lt;module&gt; State Manager</code>, <code>&lt;module&gt; NM</code>, <code>Generic NM Interface</code>) interagieren vertikal mit <code>&lt;module&gt; Interface</code>, ohne den PDU Router zu passieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm legt die verbindlichen BSW-Modulgrenzen und Schichtenhierarchien für den PDU Router fest:</p>\n<ul class=\"fig-list\">\n<li>Der PDU Router kommuniziert nach oben mit <code>AUTOSAR COM</code>, <code>Diagnostic Com. Manager</code>, <code>Debugging</code> und <code>IPDU Multiplexer</code>.</li>\n<li>Nach unten vermittelt der PDU Router zu <code>&lt;module&gt; Transport Protocol</code> und <code>&lt;module&gt; Interface</code>.</li>\n<li>Die Kommunikations-Hardwareabstraktion kapselt Treiber (<code>&lt;module&gt; Driver</code>) und Transceiver (<code>&lt;module&gt; Transceiver</code>) vollständig unterhalb von <code>&lt;module&gt; Interface</code>.</li>\n<li>Netzwerk- und Zustandsmanagement operieren unabhängig vom PDU Router direkt auf <code>&lt;module&gt; Interface</code>.</li>\n<li>Die Notation <code>&lt;module&gt;</code> signalisiert generische Modulschablonen für alle unterstützten Busstandards.</li>\n</ul>"}, {"id": "FIG-6c0a9ad0c6595ff5", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Architektur- und Schichtenmodell der AUTOSAR Classic Platform (AUTOSAR Basic Software Architecture). Das Blockschaltbild visualisiert die Einbettung des PDU Routers (PDU Router / Pdur) in die AUTOSAR-Kommunikationsarchitektur über zwei primäre Schichten: „Communication Services“ (Teil der Service-Schicht) und „Communication Hardware Abstraction“ (Kommunikations-Hardwareabstraktionsschicht). Der PDU Router fungiert dabei als zentrales Vermittlungsglied für I-PDUs zwischen oberen Kommunikationsdiensten, Transportprotokollen und busspezifischen Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert die beteiligten BSW-Module in Schichten und Funktionsgruppen:</p>\n<ul class=\"fig-list\">\n<li><strong>Communication Services (obere Schicht, violett hinterlegt):</strong></li>\n<li><strong>PDU Router</strong> (gelb hervorgehoben): Zentrale Vermittlungseinheit mit L-förmiger Topologie zur I-PDU-Verteilung.</li>\n<li>Obere PDU-Nutzer/Quellen (orange):</li>\n<li><code>AUTOSAR COM</code>: Signalbasierte Kommunikation.</li>\n<li><code>Diagnostic Com. Manager</code> (<code>Dcm</code>): Diagnose-Kommunikationsmanager.</li>\n<li><code>Debugging</code>: BSW-Debugging-Dienst.</li>\n<li><code>IPDU Multiplexer</code> (<code>IpduM</code>): Multiplexen und Demultiplexen von I-PDUs.</li>\n<li><code>Generic NM Interface</code>: Generische Netzwerkmanagement-Schnittstelle.</li>\n<li>Protokoll- und Zustandsmodule (blau):</li>\n<li><code>&lt;module&gt; Transport Protocol</code>: Busspezifisches Transportprotokoll (z. B. CanTp, FrTp, LinTp).</li>\n<li><code>&lt;module&gt; State Manager</code>: Busspezifischer Zustandsmanager (z. B. CanSM, FrSM, LinSM).</li>\n<li><code>&lt;module&gt; NM</code>: Busspezifisches Netzwerkmanagement (z. B. CanNm, FrNm).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Communication Hardware Abstraction (untere Schicht, grün hinterlegt):</strong></li>\n<li><code>&lt;module&gt; Interface</code> (blau): Busspezifische Schnittstelle zur Kommunikation mit PDU Router, Transportprotokoll und Zustandsmanagement.</li>\n<li><code>&lt;module&gt; Transceiver</code>: Transceiver-Treiber / Abstraktion unterhalb von <code>&lt;module&gt; Interface</code>.</li>\n<li><code>&lt;module&gt; Driver</code>: Hardware-Treiber / Abstraktion unterhalb von <code>&lt;module&gt; Interface</code>.</li>\n</ul>\n<p class=\"fig-p\">Die Interaktionsbeziehungen basieren auf der direkten Nachbarschaft der Schichten und Modulkanten.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Modul- und Schichtendiagramm enthält die Abbildung keine Zeitachsen, Sequenznummern oder Nachrichtenpfeile. Der Kontroll- und Datenfluss ergibt sich aus der strukturellen Anordnung:</p>\n<ul class=\"fig-list\">\n<li>Datenübertragung und Routing von I-PDUs erfolgen zwischen <code>AUTOSAR COM</code>, <code>Diagnostic Com.</code> bzw. <code>Debugging</code> und dem <code>PDU Router</code>.</li>\n<li>Der <code>PDU Router</code> leitet I-PDUs entweder direkt an <code>&lt;module&gt; Interface</code> oder an <code>&lt;module&gt; Transport Protocol</code> zur Segmentierung/Reassemblierung weiter.</li>\n<li><code>IPDU Multiplexer</code> tauscht Daten mit dem PDU Router aus, um Multiplex-PDUs vor der Weiterleitung zusammenzusetzen oder aufzuteilen.</li>\n<li>Zustands- und Netzwerkmanagement (<code>&lt;module&gt; State Manager</code>, <code>&lt;module&gt; NM</code>, <code>Generic NM Interface</code>) interagieren vertikal mit <code>&lt;module&gt; Interface</code>, ohne den PDU Router zu passieren.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm legt die verbindlichen BSW-Modulgrenzen und Schichtenhierarchien für den PDU Router fest:</p>\n<ul class=\"fig-list\">\n<li>Der PDU Router kommuniziert nach oben mit <code>AUTOSAR COM</code>, <code>Diagnostic Com. Manager</code>, <code>Debugging</code> und <code>IPDU Multiplexer</code>.</li>\n<li>Nach unten vermittelt der PDU Router zu <code>&lt;module&gt; Transport Protocol</code> und <code>&lt;module&gt; Interface</code>.</li>\n<li>Die Kommunikations-Hardwareabstraktion kapselt Treiber (<code>&lt;module&gt; Driver</code>) und Transceiver (<code>&lt;module&gt; Transceiver</code>) vollständig unterhalb von <code>&lt;module&gt; Interface</code>.</li>\n<li>Netzwerk- und Zustandsmanagement operieren unabhängig vom PDU Router direkt auf <code>&lt;module&gt; Interface</code>.</li>\n<li>Die Notation <code>&lt;module&gt;</code> signalisiert generische Modulschablonen für alle unterstützten Busstandards.</li>\n</ul>"}, {"id": "FIG-696d742a7ea76d16", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Architektur- und Schichtenmodell der AUTOSAR Classic Platform (AUTOSAR Basic Software Architecture). Das Blockschaltbild visualisiert die Einbettung des PDU Routers (PDU Router / Pdur) in die AUTOSAR-Kommunikationsarchitektur über zwei primäre Schichten: „Communication Services“ (Teil der Service-Schicht) und „Communication Hardware Abstraction“ (Kommunikations-Hardwareabstraktionsschicht). Der PDU Router fungiert dabei als zentrales Vermittlungsglied für I-PDUs zwischen oberen Kommunikationsdiensten, Transportprotokollen und busspezifischen Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm strukturiert die AUTOSAR-Kommunikationsarchitektur in Schichten und Funktionsmodule:</p>\n<ul class=\"fig-list\">\n<li><strong>Communication Services (obere Schicht, violett hinterlegt):</strong></li>\n<li><strong>PDU Router</strong> (gelb hervorgehoben): Zentrales Vermittlungsmodul zur Weiterleitung von I-PDUs.</li>\n<li>Obere Kommunikationsmodule (orange):</li>\n<li><code>DCM</code>: Diagnostic Communication Manager für Diagnoseanfragen und -antworten.</li>\n<li><code>COM</code>: Signalbasierte Kommunikationsschicht (AUTOSAR COM).</li>\n<li><code>DLT</code>: Diagnostic Log and Trace für Logging- und Tracedaten.</li>\n<li><code>Debugging</code>: Modul zur BSW-Fehlerbehebung und -Analyse.</li>\n<li><code>IPDU Multiplexer</code>: Modul zur Aggregation und Verteilung multiplexierter I-PDUs.</li>\n<li><code>Generic NM Interface</code>: Einheitliche Netzwerkmanagement-Schnittstelle.</li>\n<li>Protokoll- und Zustandsmodule (blau):</li>\n<li><code>&lt;module&gt; Transport Protocol</code>: Busspezifisches Transportprotokoll.</li>\n<li><code>&lt;module&gt; State Manager</code>: Busspezifisches Modul zur Verwaltung des Kommunikationszustands.</li>\n<li><code>&lt;module&gt; NM</code>: Busspezifisches Netzwerkmanagement-Modul.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Communication Hardware Abstraction (untere Schicht, grün hinterlegt):</strong></li>\n<li><code>&lt;module&gt; Interface</code> (blau): Schnittstellenabstraktion zur Vermittlung an den PDU Router, das Transportprotokoll und den Zustandsmanager.</li>\n<li><code>&lt;module&gt; Transceiver</code> (blau): Transceiver-Steuerung.</li>\n<li><code>&lt;module&gt; Driver</code> (blau): Direkte Hardware-Treiberabstraktion.</li>\n</ul>\n<p class=\"fig-p\">Die Kommunikationspfade verlaufen vertikal zwischen den oberen Kommunikationsmodulen (<code>DCM</code>, <code>COM</code>, <code>DLT</code>, <code>Debugging</code>), dem <code>PDU Router</code> und den darunterliegenden Schichten.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statische Architekturübersicht stellt das Diagramm keine dynamischen Sequenzen oder Nachrichtentransfers dar. Der funktionale Ablauf ergibt sich aus der Architekturtopologie:</p>\n<ul class=\"fig-list\">\n<li>Obere Module (<code>DCM</code>, <code>COM</code>, <code>DLT</code>, <code>Debugging</code>) initiieren oder empfangen I-PDUs über den <code>PDU Router</code>.</li>\n<li>Der <code>PDU Router</code> vermittelt I-PDUs an den <code>IPDU Multiplexer</code> oder direkt an <code>&lt;module&gt; Interface</code> (für unsegmentierte Übertragung) bzw. an <code>&lt;module&gt; Transport Protocol</code> (für segmentierte Übertragung).</li>\n<li><code>&lt;module&gt; Interface</code> steuert den Zugriff über <code>&lt;module&gt; Driver</code> und <code>&lt;module&gt; Transceiver</code>.</li>\n<li>Steuer- und Zustandsflüsse des Netzwerkmanagements (<code>Generic NM Interface</code>, <code>&lt;module&gt; NM</code>, <code>&lt;module&gt; State Manager</code>) umgehen den Datenpfad des PDU Routers.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische und normative Vorgaben für den PDU Router und dessen Systemumgebung:</p>\n<ul class=\"fig-list\">\n<li>Der PDU Router ist standardmäßig angebunden an <code>COM</code>, <code>DCM</code>, <code>DLT</code>, <code>Debugging</code> sowie <code>IPDU Multiplexer</code>.</li>\n<li>Bei der Integration von <code>DLT</code> über den Kommunikationsstapel ist der Routingpfad über den PDU Router normativ vorgesehen.</li>\n<li>Klare Trennung zwischen Datenrouting (PDU Router, Transportprotokolle, Interfaces) und Steuerungsfunktionen (State Manager, NM-Module).</li>\n<li>Der Platzhalter <code>&lt;module&gt;</code> repräsentiert die jeweiligen Kommunikationscontroller und Busarten (CAN, LIN, FlexRay, Ethernet).</li>\n</ul>"}, {"id": "FIG-5f06e86d9800077c", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Statisches Architektur- und Schichtenmodell der AUTOSAR Classic Platform (AUTOSAR Basic Software Architecture). Das Blockschaltbild visualisiert die Einbettung des PDU Routers (PDU Router / Pdur) in die AUTOSAR-Kommunikationsarchitektur über zwei primäre Schichten: „Communication Services“ (Teil der Service-Schicht) und „Communication Hardware Abstraction“ (Kommunikations-Hardwareabstraktionsschicht). Der PDU Router fungiert dabei als zentrales Vermittlungsglied für I-PDUs zwischen oberen Kommunikationsdiensten, Transportprotokollen und busspezifischen Schnittstellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm strukturiert die AUTOSAR-Kommunikationsarchitektur in Schichten und Module:</p>\n<ul class=\"fig-list\">\n<li><strong>Communication Services (obere Schicht, violett hinterlegt):</strong></li>\n<li><strong>PDU Router</strong> (gelb hervorgehoben): Zentrales Vermittlungsmodul zur Weiterleitung von I-PDUs.</li>\n<li>Obere Kommunikationsmodule (orange):</li>\n<li><code>DCM</code>: Diagnostic Communication Manager für Diagnose-PDUs.</li>\n<li><code>COM</code>: Signalbasierte Kommunikation (AUTOSAR COM).</li>\n<li><code>DLT</code>: Diagnostic Log and Trace für Protokoll- und Tracing-Nachrichten.</li>\n<li><code>IPDU Multiplexer</code>: Multiplexen und Demultiplexen von I-PDUs.</li>\n<li><code>Generic NM Interface</code>: Abstrahierendes Netzwerkmanagement-Interface.</li>\n<li>Protokoll- und Zustandsmodule (blau):</li>\n<li><code>&lt;module&gt; Transport Protocol</code>: Busspezifisches Transportprotokoll für segmentierte Übertragungen.</li>\n<li><code>&lt;module&gt; State Manager</code>: Busspezifische Zustandsverwaltung der Kommunikationskanäle.</li>\n<li><code>&lt;module&gt; NM</code>: Busspezifisches Netzwerkmanagement.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong>Communication Hardware Abstraction (untere Schicht, grün hinterlegt):</strong></li>\n<li><code>&lt;module&gt; Interface</code> (blau): Hardwareabstrahierte Schnittstelle zum PDU Router, zum Transportprotokoll und zum State Manager.</li>\n<li><code>&lt;module&gt; Transceiver</code> (blau): Modul zur Transceiver-Ansteuerung.</li>\n<li><code>&lt;module&gt; Driver</code> (blau): Modul zur Controller-Treiberansteuerung.</li>\n</ul>\n<p class=\"fig-p\">Die Schnittstellenbeziehungen ergeben sich aus den Berührungsflächen der Blöcke.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches Architekturmodell bildet die Grafik keine Zeitleisten oder Kontrollflussdiagramme ab. Aus der strukturellen Lage ergeben sich folgende Daten- und Steuerpfade:</p>\n<ul class=\"fig-list\">\n<li>Nutzdaten- und Diagnosedatenströme fließen zwischen den oberen Modulen (<code>DCM</code>, <code>COM</code>, <code>DLT</code>) und dem <code>PDU Router</code>.</li>\n<li>Der <code>PDU Router</code> verteilt I-PDUs entweder über den <code>IPDU Multiplexer</code>, leitet sie direkt an <code>&lt;module&gt; Interface</code> weiter oder übergibt sie zwecks Segmentierung an <code>&lt;module&gt; Transport Protocol</code>.</li>\n<li>Über <code>&lt;module&gt; Interface</code> werden I-PDUs an <code>&lt;module&gt; Driver</code> übergeben bzw. von dort empfangen.</li>\n<li>Der Kontrollpfad für Netzwerkmanagement und Zustandssteuerung (<code>Generic NM Interface</code>, <code>&lt;module&gt; NM</code>, <code>&lt;module&gt; State Manager</code>) verläuft separat am PDU Router vorbei direkt zu <code>&lt;module&gt; Interface</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben und Konfigurationsrahmen für den PDU Router:</p>\n<ul class=\"fig-list\">\n<li>Als obere Kommunikationspartner des PDU Routers sind <code>COM</code>, <code>DCM</code>, <code>DLT</code> sowie <code>IPDU Multiplexer</code> spezifiziert; ein eigenständiges Modul „Debugging“ existiert im Kommunikationsdatenpfad oberhalb des PDU Routers nicht.</li>\n<li>Die Verteilung von I-PDUs erfolgt strikt zwischen den genannten oberen Schichten und den unteren Kommunikationsschnittstellen (<code>&lt;module&gt; Interface</code> sowie <code>&lt;module&gt; Transport Protocol</code>).</li>\n<li>Trennung von Nutzdatenpfad (über PDU Router) und Managementpfad (<code>&lt;module&gt; State Manager</code> und NM-Stack).</li>\n<li>Der Präfix <code>&lt;module&gt;</code> steht für die busspezifischen Instanziierungen der Kommunikations-Hardwareabstraktion und Transportprotokolle.</li>\n</ul>"}], "trans": [{"from": "FIG-19abcb0e490c8c0f", "to": "FIG-d9d6dc4d731ac15d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>In der Schicht „Communication Services“ wurde die Modulbeschriftung „Diagnostic Com.“ zu „Diagnostic Com. Manager“ präzisiert.</li>\n<li>In der Schicht „Communication Hardware Abstraction“ wurden die beiden zuvor unbeschrifteten Modulblöcke unterhalb von „<module> Interface“ mit „<module> Transceiver“ und „<module> Driver“ beschriftet.</li>\n</ul>"}, {"from": "FIG-d9d6dc4d731ac15d", "to": "FIG-6c0a9ad0c6595ff5", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6c0a9ad0c6595ff5", "to": "FIG-696d742a7ea76d16", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In der Schicht „Communication Services“ oberhalb des PDU Routers wurde das Modul „DLT“ (Diagnostic Log and Trace) als oberer Kommunikationsdienst ergänzt.</li>\n<li>Die Modulbezeichnungen im oberen Bereich wurden angepasst: „Diagnostic Com. Manager“ wurde zu „DCM“, „AUTOSAR COM“ zu „COM“ und „Debugging“ (vormals „Debugg ing“) wurde neu ausgerichtet.</li>\n<li>Das Modul „IPDU Multiplexer“ (vormals „IPDU Multiple xer“) wurde neu gesetzt.</li>\n</ul>"}, {"from": "FIG-696d742a7ea76d16", "to": "FIG-5f06e86d9800077c", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Das Modul „Debugging“ innerhalb der „Communication Services“ oberhalb des PDU Routers wurde entfernt.</li>\n</ul>"}]};
